class Box:
    def __init__(self, n):
        self.n = n
    def __add__(self, other):
        return Box(self.n + other.n)


def main():
    a = Box(3)
    b = a + Box(4)
    print(b.n, a.n)


if __name__ == "__main__":
    main()
